{"command":"set -o pipefail
for args in "" "--help" "-h" "--version" "-V" "-v"; do
  printf '\n===== ./executable %s =====\n' "$args"
  timeout 5 ./executable $args </dev/null >out.tmp 2>err.tmp; rc=$?; echo "[exit $rc]"; echo "--- stdout ---"; sed -n '1,120p' out.tmp; echo "--- stderr ---"; sed -n '1,120p' err.tmp; 
done
rm -f out.tmp err.tmp"}

