{"command":"cmpcase(){ args="$1"; input="$2"; echo "===== $args ====="; printf '%b' "$input" | ./executable $args >/tmp/ref.out 2>/tmp/ref.err; printf '%b' "$input" | PROJ_CLONE_PROGNAME=executable python3 src/proj_clone.py $args >/tmp/new.out 2>/tmp/new.err; diff -u /tmp/ref.out /tmp/new.out || true; }
cmpcase '+proj=utm +zone=32' '10 20\n9 0\n12 55\n'
